//! 📦️ The three package members retain inline metadata and write bounded stored ZIP records under original output grants.
use crate::output::{ChunkRope,OutputWork};
use std::mem::{MaybeUninit,size_of};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum PackageMember{Document,Preflight,Manifest}
impl PackageMember{pub fn name(self)->&'static str{match self{Self::Document=>"document.json",Self::Preflight=>"preflight-report.json",Self::Manifest=>"package-manifest.json"}}fn ordinal(self)->usize{self as usize}}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct ZipEntry{pub member:PackageMember,pub crc:u32,pub size:u32,pub offset:u32}
#[derive(Clone,Debug,Default,PartialEq,Eq)]pub struct ZipState{pub entries:[Option<ZipEntry>;3],pub count:usize,pub current:Option<PackageMember>,pub current_crc:u32,pub current_size:u32,pub current_offset:u32}
impl ZipState{pub fn entry(&self,index:usize)->Option<ZipEntry>{self.entries.get(index).copied().flatten()}pub fn pop(&mut self)->Option<ZipEntry>{if self.count==0{return None}self.count-=1;self.entries[self.count].take()}pub fn terminal_is_empty(&self)->bool{self.count==0&&self.current.is_none()&&self.entries.iter().all(Option::is_none)}}
struct Fragment{bytes:[MaybeUninit<u8>;96],len:usize}
impl Fragment{
 fn new()->Self{Self{bytes:[MaybeUninit::uninit();96],len:0}}
 fn bytes(&self)->&[u8]{unsafe{std::slice::from_raw_parts(self.bytes.as_ptr().cast::<u8>(),self.len)}}
 fn append(&mut self,bytes:&[u8]){assert!(self.len+bytes.len()<=96);for byte in bytes{self.bytes[self.len].write(*byte);self.len+=1}}
 fn u16(&mut self,value:u16){self.append(&value.to_le_bytes())}fn u32(&mut self,value:u32){self.append(&value.to_le_bytes())}
 fn local(member:PackageMember)->Self{let mut f=Self::new();f.u32(0x04034b50);f.u16(20);f.u16(8);f.u16(0);f.u16(0);f.u16(33);f.u32(0);f.u32(0);f.u32(0);f.u16(member.name().len()as u16);f.u16(0);f.append(member.name().as_bytes());f}
 fn descriptor(entry:ZipEntry)->Self{let mut f=Self::new();f.u32(0x08074b50);f.u32(entry.crc);f.u32(entry.size);f.u32(entry.size);f}
 fn central(entry:ZipEntry)->Self{let mut f=Self::new();f.u32(0x02014b50);f.u16(20);f.u16(20);f.u16(8);f.u16(0);f.u16(0);f.u16(33);f.u32(entry.crc);f.u32(entry.size);f.u32(entry.size);f.u16(entry.member.name().len()as u16);f.u16(0);f.u16(0);f.u16(0);f.u16(0);f.u32(0);f.u32(entry.offset);f.append(entry.member.name().as_bytes());f}
 fn end(count:u16,size:u32,offset:u32)->Self{let mut f=Self::new();f.u32(0x06054b50);f.u16(0);f.u16(0);f.u16(count);f.u16(count);f.u32(size);f.u32(offset);f.u16(0);f}
}
const METADATA:usize=size_of::<ZipState>()*2+size_of::<Fragment>()*2;
fn admit(output:&ChunkRope,length:usize,inspection:usize,work:&mut OutputWork)->Result<bool,String>{if output.len.checked_add(length).is_none_or(|n|n>crate::MAX_LAYOUT_EXPORT_OUTPUT_BYTES){return Err("layout-export-output-limit".into())}if !output.has_room(length){return Ok(false)}let depth=output.write_depth().map_err(|_|"layout-output-path-demand")?;let g=work.remaining();let copy=METADATA+inspection+length+size_of::<usize>()*3;if g.maximum_items<2||g.maximum_copy_bytes<copy||g.maximum_depth<depth.max(1){return Ok(false)}work.copy(METADATA+inspection,1)?;Ok(true)}
pub(super) fn begin(state:&mut ZipState,output:&mut ChunkRope,member:PackageMember,work:&mut OutputWork)->Result<bool,String>{if state.current.is_some()||state.count>=3||state.count!=member.ordinal(){return Err("layout-export-package-entry-state".into())}let offset=u32::try_from(output.len).map_err(|_|"layout-export-output-limit")?;if !admit(output,30+member.name().len(),0,work)?{return Ok(false)}let header=Fragment::local(member);output.append(header.bytes(),work)?;state.current=Some(member);state.current_offset=offset;state.current_crc=0;state.current_size=0;Ok(true)}
pub(super) fn data(state:&mut ZipState,output:&mut ChunkRope,bytes:&[u8],work:&mut OutputWork)->Result<bool,String>{if state.current.is_none(){return Err("layout-export-package-no-entry".into())}if bytes.len()>crate::OUTPUT_CHUNK_BYTES{return Err("layout-export-package-body-limit".into())}if bytes.is_empty(){return Ok(true)}let size=state.current_size.checked_add(u32::try_from(bytes.len()).map_err(|_|"layout-export-output-limit")?).ok_or("layout-export-output-limit")?;if !admit(output,bytes.len(),bytes.len(),work)?{return Ok(false)}let crc=crate::crc32_update(state.current_crc,bytes);output.append(bytes,work)?;state.current_crc=crc;state.current_size=size;Ok(true)}
pub(super) fn finish(state:&mut ZipState,output:&mut ChunkRope,work:&mut OutputWork)->Result<bool,String>{let member=state.current.ok_or("layout-export-package-no-entry")?;if state.count>=3{return Err("layout-export-package-entry-state".into())}if !admit(output,16,0,work)?{return Ok(false)}let entry=ZipEntry{member,crc:state.current_crc,size:state.current_size,offset:state.current_offset};output.append(Fragment::descriptor(entry).bytes(),work)?;state.entries[state.count]=Some(entry);state.count+=1;state.current=None;Ok(true)}
pub(super) fn central(entry:ZipEntry,output:&mut ChunkRope,work:&mut OutputWork)->Result<bool,String>{if !admit(output,46+entry.member.name().len(),0,work)?{return Ok(false)}output.append(Fragment::central(entry).bytes(),work)?;Ok(true)}
pub(super) fn end(state:&ZipState,output:&mut ChunkRope,central_offset:u32,work:&mut OutputWork)->Result<bool,String>{if state.current.is_some()||state.count!=3{return Err("layout-export-package-entry-state".into())}let end=u32::try_from(output.len).map_err(|_|"layout-export-output-limit")?;let size=end.checked_sub(central_offset).ok_or("layout-export-package-central-offset")?;if !admit(output,22,0,work)?{return Ok(false)}output.append(Fragment::end(state.count as u16,size,central_offset).bytes(),work)?;Ok(true)}
